  'A Year 3 core course that equips undergraduate public health students to understand, analyze, manage, and improve health policies, healthcare organizations, and public health systems. It integrates institutions, federalism, financing, coverage, access, quality, law, politics, comparative systems, leadership, budgeting, workforce, implementation, equity, emergency resilience, and applied policy analysis.',
  $hpmjson${"slug": "health-policy-and-management", "title": "Health Policy and Management", "description": "A Year 3 core course that equips undergraduate public health students to understand, analyze, manage, and improve health policies, healthcare organizations, and public health systems. It integrates institutions, federalism, financing, coverage, access, quality, law, politics, comparative systems, leadership, budgeting, workforce, implementation, equity, emergency resilience, and applied policy analysis.", "topics": [{"id": "12c59872-5924-4a5f-8fcf-79e7ab4961cc", "type": "topic", "title": "Health Policy Process", "description": "Introduces how problems reach agendas, policy alternatives are developed, decisions are authorized, programs are implemented, and outcomes feed back into future policy.", "children": [{"id": "4d746a31-c5bc-4ba8-9d59-5949c65222ad", "type": "subtopic", "title": "Problem definition and agenda setting", "description": "Students learn that how a problem is framed determines which solutions and stakeholders become legitimate.", "children": [{"id": "f558af54-1f93-40d1-be73-642dbe031e33", "type": "concept", "title": "Indicators, focusing events, and feedback"}, {"id": "0ca9f5f2-c037-44ab-89b6-a160bdf12bee", "type": "concept", "title": "Problem frames and causal stories"}, {"id": "ac8a0507-8fb7-4d93-a0ac-5b523e046492", "type": "concept", "title": "Agenda windows"}, {"id": "1ca3a0d4-518c-46c2-8494-86a2a3a6eecc", "type": "concept", "title": "Issue attention cycles"}]}, {"id": "1f8f9dac-2e5d-4dae-8406-57ed738a7d88", "type": "subtopic", "title": "Formulation and adoption", "description": "Policy alternatives must survive evidence, values, legal authority, politics, and procedural rules.", "children": [{"id": "d3a180cc-ee3f-4a2b-8731-7c33d794ab1a", "type": "concept", "title": "Legislative and administrative pathways"}, {"id": "1ab8b6dc-1e9e-4067-8831-5b6d42f9c614", "type": "concept", "title": "Policy instruments"}, {"id": "69b79f35-d954-46a2-a0ed-ad5a3c93910d", "type": "concept", "title": "Committee, rulemaking, and budgeting processes"}, {"id": "f0ffe53b-21f5-4637-8152-6511378d7dde", "type": "concept", "title": "Coalitions and negotiation"}]}, {"id": "04b72467-5118-4ad6-9baa-7fd8e32873a7", "type": "subtopic", "title": "Implementation and evaluation", "description": "Adoption is only the midpoint; delivery capacity and feedback determine actual effects.", "children": [{"id": "4d0f3bc2-9323-493b-b890-f76a924c049c", "type": "concept", "title": "Administrative discretion"}, {"id": "f29f6878-a40f-495d-822c-2cc9359131e6", "type": "concept", "title": "Implementation fidelity and adaptation"}, {"id": "676bad5f-56dd-4ff2-82c8-47f4a151723e", "type": "concept", "title": "Process, outcome, and impact evaluation"}, {"id": "c7f30582-d330-44db-b04e-340e0b6986c2", "type": "concept", "title": "Policy feedback and termination"}]}]}, {"id": "2fcfdd99-1920-4566-8c01-86ad1635e483", "type": "topic", "title": "Federal Health Institutions and Intergovernmental Relations", "description": "Maps the authorities, incentives, data, financing, regulation, and coordination roles of federal institutions and their relationships with states, tribes, territories, and localities.", "children": [{"id": "61116902-9f6a-468b-bcc5-e05855894b10", "type": "subtopic", "title": "Federal actors and functions", "description": "Students map who finances, regulates, researches, delivers, and coordinates health policy.", "children": [{"id": "9dd425aa-97e6-43e0-8344-1693d7af71f9", "type": "concept", "title": "HHS, CDC, CMS, FDA, NIH, HRSA, and AHRQ"}, {"id": "dc88e091-aabe-40af-869d-99d5e6bc9a9c", "type": "concept", "title": "Congress and the executive branch"}, {"id": "6b4f148e-521c-4627-b41f-cc1a9c400328", "type": "concept", "title": "Courts and independent bodies"}, {"id": "8c2cddbe-3f91-4435-a615-19f3b07e4286", "type": "concept", "title": "Federal data and accountability systems"}]}, {"id": "edcebc8f-4fd6-446a-861a-3fffc13aa37d", "type": "subtopic", "title": "Federalism", "description": "Shared authority creates innovation and responsiveness as well as fragmentation and inequity.", "children": [{"id": "9d6b9de3-ef56-4e8f-9e1b-c5546c98bd98", "type": "concept", "title": "Enumerated and reserved powers"}, {"id": "c129f89f-1ea0-4042-aae2-790fd258f98d", "type": "concept", "title": "Grants, waivers, and conditions"}, {"id": "34571928-2f53-4386-b88f-46f3821e700f", "type": "concept", "title": "Preemption"}, {"id": "8e78714a-6401-467e-87a3-5403a74c5387", "type": "concept", "title": "Interstate variation"}]}, {"id": "40dccf11-4adb-4393-91c9-999bd661c617", "type": "subtopic", "title": "Intergovernmental coordination", "description": "Public health threats and programs cross borders and require clear roles and mutual support.", "children": [{"id": "bd1fda86-3676-434d-a05d-78b0f99c8817", "type": "concept", "title": "Federal–state–local relationships"}, {"id": "3f410278-650d-4032-ba91-5bd216c909fe", "type": "concept", "title": "Tribal sovereignty"}, {"id": "edca6dc8-c766-43f2-b10d-7db577d1c62a", "type": "concept", "title": "Territories and freely associated states"}, {"id": "b49447bf-ac17-441d-a770-d3d6a56bd804", "type": "concept", "title": "Mutual aid and cross-jurisdiction agreements"}]}]}, {"id": "1b4822c1-8413-4606-9df1-892111787575", "type": "topic", "title": "State, Tribal, Territorial, and Local Public Health Systems", "description": "Shows how public health authority and service delivery vary across jurisdictions and how agencies work with healthcare, community, and cross-sector partners.", "children": [{"id": "ae10ed3f-cd42-4169-87b5-10d5801a1707", "type": "subtopic", "title": "System structures", "description": "Students compare centralized, decentralized, shared, and mixed governance arrangements.", "children": [{"id": "c8ec4604-f5d1-4ec4-a129-dd2fb927d366", "type": "concept", "title": "State health agencies"}, {"id": "6f64c08c-fb5e-4011-852c-b858c179597b", "type": "concept", "title": "Local health departments"}, {"id": "6d4a9c8e-4a65-4f54-baf6-eed84f6bb99d", "type": "concept", "title": "Boards of health"}, {"id": "3b8c766a-8469-4215-ab60-8163973a822c", "type": "concept", "title": "Tribal public health authorities"}]}, {"id": "607fabd1-92be-4e4e-b471-cf34a5ddd994", "type": "subtopic", "title": "Essential services and partnerships", "description": "Government agencies rarely produce population health alone.", "children": [{"id": "51b5bd4e-e84a-461c-a343-b9e2c68e4599", "type": "concept", "title": "Assessment, policy development, and assurance"}, {"id": "24ba0360-9482-4200-bbb1-16adb9373b24", "type": "concept", "title": "Healthcare and community partnerships"}, {"id": "825ba12b-f498-4320-87f6-c498ce29af81", "type": "concept", "title": "Schools, housing, transportation, and environment"}, {"id": "bfda28e9-325b-4306-a938-c64a86730bdb", "type": "concept", "title": "Academic–practice collaboration"}]}, {"id": "7a94b078-34ab-4043-913f-5f5e05c05124", "type": "subtopic", "title": "Capacity and accountability", "description": "Local variation in funding, workforce, authority, and data shapes what systems can deliver.", "children": [{"id": "63418563-d35a-4aab-b9dc-d27e9269648a", "type": "concept", "title": "Accreditation and performance"}, {"id": "b89a451f-c1dd-438e-b98a-5b22d20d32aa", "type": "concept", "title": "Rural and urban capacity"}, {"id": "2a5021c2-733f-40fc-8bfd-49f0da88c688", "type": "concept", "title": "Regionalization and shared services"}, {"id": "6f5daa74-e695-4c87-9b91-df9f359709f0", "type": "concept", "title": "Public reporting and community oversight"}]}]}, {"id": "6f64cafc-ac9d-4bd8-9afe-757610b1398b", "type": "topic", "title": "Healthcare Financing and Payment Policy", "description": "Explains revenue, risk pooling, purchasing, provider payment, public budgets, and incentives that shape cost, access, quality, and population health.", "children": [{"id": "09e9569c-c13a-4a66-8079-5d602e788aa4", "type": "subtopic", "title": "Financing functions", "description": "Students distinguish raising money, pooling risk, purchasing services, and paying providers.", "children": [{"id": "48a59658-14b9-46bb-928b-cb57d45147a7", "type": "concept", "title": "Taxes, premiums, and out-of-pocket payment"}, {"id": "26205f2a-006a-41b9-90f7-f35901ccf681", "type": "concept", "title": "Risk pooling"}, {"id": "a878904c-8246-44f9-9be6-815b3b853b43", "type": "concept", "title": "Benefit design"}, {"id": "8e943c48-dbd1-4149-8118-72520928834f", "type": "concept", "title": "Strategic purchasing"}]}, {"id": "d897ace6-517e-4f61-9292-416b608c6fa4", "type": "subtopic", "title": "Provider payment and incentives", "description": "Payment rules shape volume, coordination, selection, quality, and financial risk.", "children": [{"id": "817727f9-b6f6-44e5-ab29-623ac0394ec0", "type": "concept", "title": "Fee-for-service"}, {"id": "df70e0c1-4dbf-4101-b068-ebec2e8603d8", "type": "concept", "title": "Capitation and global budgets"}, {"id": "f0722d8a-d199-4946-a283-e646e7ae1db6", "type": "concept", "title": "Bundled payment"}, {"id": "87b4533f-95af-434e-bc99-7b644b4d9ce8", "type": "concept", "title": "Value-based purchasing and pay-for-performance"}]}, {"id": "d12a633a-ba63-40c9-950f-13e9391925f5", "type": "subtopic", "title": "Cost and expenditure analysis", "description": "Students connect prices, utilization, intensity, administration, and population need to spending.", "children": [{"id": "1c46e0c9-fc21-4705-889a-87b603fa445a", "type": "concept", "title": "National health expenditures"}, {"id": "4539f444-0b02-4a6e-ad84-0472edde174a", "type": "concept", "title": "Unit price versus volume"}, {"id": "9c1af70b-da81-4561-a298-e5fc7f8c582a", "type": "concept", "title": "Cost shifting and market power"}, {"id": "ad8b8182-0520-4205-8347-96042deb1ad0", "type": "concept", "title": "Budget impact and fiscal sustainability"}]}]}, {"id": "e58af264-4bba-4523-b5e3-7a5bc1efe858", "type": "topic", "title": "Coverage, Access, and Universal Health Protection", "description": "Examines insurance, eligibility, affordability, provider availability, nonfinancial barriers, and policy strategies for equitable access and financial protection.", "children": [{"id": "fcd751db-cd3c-487b-98c2-c116e5ad3e6a", "type": "subtopic", "title": "Coverage architecture", "description": "Students compare public programs, employer coverage, individual markets, and safety-net arrangements.", "children": [{"id": "059ab567-e8f0-4ce3-b25f-016ec5a1a2bc", "type": "concept", "title": "Medicare and Medicaid"}, {"id": "f758d569-840c-4da7-bca6-0c8e567275a4", "type": "concept", "title": "Employer-sponsored insurance"}, {"id": "76dbf3ac-2119-4e3d-be4b-dfe753b48377", "type": "concept", "title": "Marketplace coverage"}, {"id": "4e70a648-fc7f-415a-b96d-f8377b4a0cd8", "type": "concept", "title": "Uninsured and underinsured populations"}]}, {"id": "be44e51e-31b6-4a3f-86e2-b5a8e44e4bec", "type": "subtopic", "title": "Access dimensions", "description": "Insurance does not guarantee timely, acceptable, geographically available care.", "children": [{"id": "8df21cbd-4f88-46ba-b91b-9d8100dfca7d", "type": "concept", "title": "Affordability"}, {"id": "ee196471-ff09-4364-a119-70e9fa462cd5", "type": "concept", "title": "Availability and workforce"}, {"id": "664a8354-6774-48e6-bb74-a80b66c9c3f2", "type": "concept", "title": "Geographic accessibility"}, {"id": "578de477-eff8-45df-910e-06e8f208264d", "type": "concept", "title": "Acceptability, language, and trust"}]}, {"id": "9f11e1b8-6a1d-4196-8106-630cfdd0cd21", "type": "subtopic", "title": "Financial protection and equity", "description": "Coverage policy redistributes resources and exposure to medical financial risk.", "children": [{"id": "d18c2de5-370a-41b1-9589-54e0fe1d429a", "type": "concept", "title": "Premiums and cost sharing"}, {"id": "b2f1ba5a-6737-474b-87c1-a3f8f1b8aff0", "type": "concept", "title": "Medical debt"}, {"id": "681d06c9-699d-484e-a078-a5239da37639", "type": "concept", "title": "Benefit adequacy"}, {"id": "860eef5e-8c97-4b0e-8080-a871d2fba5b2", "type": "concept", "title": "Universal coverage strategies"}]}]}, {"id": "37a19cf9-cbe3-428c-b878-c5a02a631d96", "type": "topic", "title": "Quality, Patient Safety, and Performance Policy", "description": "Develops the ability to define, measure, compare, and improve quality and safety without confusing easily measured activity with meaningful outcomes.", "children": [{"id": "02a388f6-5e2e-4836-9066-ca4f48fda218", "type": "subtopic", "title": "Quality frameworks", "description": "Students define quality before selecting measures or interventions.", "children": [{"id": "c5cc9940-71a1-45ed-aef3-3b1e39baa5e5", "type": "concept", "title": "Structure, process, and outcome"}, {"id": "bcf8d688-d15f-40d0-871a-a0790313622f", "type": "concept", "title": "Safety, effectiveness, timeliness, efficiency, equity, and patient-centeredness"}, {"id": "03ab871d-c709-41ac-9630-5ff59602f6b5", "type": "concept", "title": "Population versus clinical quality"}, {"id": "549c4177-6078-45fb-8292-50193f19b569", "type": "concept", "title": "Experience and reported outcomes"}]}, {"id": "4a454586-d0c0-48ce-ba89-0f2bb1f67540", "type": "subtopic", "title": "Measurement and accountability", "description": "Measures can improve transparency while also creating gaming and burden.", "children": [{"id": "f185b908-38fa-4629-b997-029b2adc1f05", "type": "concept", "title": "Numerators, denominators, and risk adjustment"}, {"id": "907f6d56-d9ae-4e34-9663-30e28845aee9", "type": "concept", "title": "Dashboards and public reporting"}, {"id": "be658c22-5b05-4b12-af9b-3c056c1f6f6e", "type": "concept", "title": "Accreditation and regulation"}, {"id": "2dad26ed-c570-4af5-9281-e285f81df11a", "type": "concept", "title": "Unintended consequences"}]}, {"id": "09ff6e7b-40d7-4633-93cb-f5079a6e9977", "type": "subtopic", "title": "Improvement methods", "description": "Students use systems thinking to test changes rather than blame individuals.", "children": [{"id": "02060916-ea04-4381-a541-6a195d8a7f61", "typ