sis", "description": "Ethics makes values and burdens visible when law alone does not resolve a choice.", "children": [{"id": "5991d27b-1054-4d88-8b3a-85e43ad14ad0", "type": "concept", "title": "Utility and harm prevention"}, {"id": "60a955b5-ec92-4538-a69b-b8173b3b4675", "type": "concept", "title": "Justice and equity"}, {"id": "d6fea102-6e6b-428a-93c6-c907e5b1882a", "type": "concept", "title": "Autonomy and solidarity"}, {"id": "238b6a2d-71cc-4139-b2a7-120334c20693", "type": "concept", "title": "Proportionality, reciprocity, and transparency"}]}]}, {"id": "665692d3-a78c-4339-9d82-1d1d1de34114", "type": "topic", "title": "Politics, Power, Stakeholders, and Advocacy", "description": "Makes visible how institutions, interests, ideology, evidence, narrative, media, lobbying, and public participation shape health decisions.", "children": [{"id": "460268aa-b1c7-4110-812b-eac4ba8ff9b7", "type": "subtopic", "title": "Institutions and power", "description": "Students examine formal authority and informal influence over agendas, evidence, and resources.", "children": [{"id": "c0fdefb9-4d37-4409-8803-ee2d7e1668dd", "type": "concept", "title": "Veto points"}, {"id": "3534c9bb-4033-4211-bc78-aa419c3c0164", "type": "concept", "title": "Interest groups and lobbying"}, {"id": "17d6310e-c023-43d9-b1e6-341d1abe22c7", "type": "concept", "title": "Professional and industry power"}, {"id": "30edbed5-d51c-4794-9ef1-cd37c190c0d8", "type": "concept", "title": "Bureaucratic and expert authority"}]}, {"id": "b83b2159-aad7-433a-b895-01dd36f39cc4", "type": "subtopic", "title": "Public opinion and communication", "description": "Narratives, trust, identity, media, and polling influence policy feasibility.", "children": [{"id": "6c3d9a92-7a68-4232-92ac-156737c84d23", "type": "concept", "title": "Framing and message testing"}, {"id": "c8081c2e-4651-4e21-b100-23e942906332", "type": "concept", "title": "Misinformation"}, {"id": "49cc2ea3-95d1-4df9-bc74-41d1fd96524e", "type": "concept", "title": "Risk communication"}, {"id": "3cdbf675-d7ab-44b9-bb96-979fd5b96841", "type": "concept", "title": "Deliberation and public engagement"}]}, {"id": "aa250400-2f69-4d50-ae27-9284788cf0bd", "type": "subtopic", "title": "Advocacy and coalition strategy", "description": "Ethical advocacy requires clear goals, stakeholder analysis, tactics, and accountability.", "children": [{"id": "26d07966-ef68-4f04-9c4b-026b8bb21884", "type": "concept", "title": "Power mapping"}, {"id": "53dbadd2-ea91-453b-b5a9-a6b3a803e3a2", "type": "concept", "title": "Coalition building"}, {"id": "efbb8c20-7e50-4ecb-9e06-f17cb4a8e70f", "type": "concept", "title": "Legislative and administrative advocacy"}, {"id": "5ec03171-6f1b-4a68-852c-58d3f0786176", "type": "concept", "title": "Grassroots, grasstops, and community organizing"}]}]}, {"id": "944faaf2-8231-458b-822c-7b922ec87f85", "type": "topic", "title": "Comparative and Global Health Systems", "description": "Uses cross-national comparison to understand alternative arrangements for financing, governance, service delivery, workforce, medicines, and universal coverage.", "children": [{"id": "55fb6850-38b0-46d6-bd0d-0ffc3447b276", "type": "subtopic", "title": "Comparison framework", "description": "Students compare functions and outcomes rather than relying on country labels.", "children": [{"id": "acf80b64-f208-493f-a1fd-a551eaed9ed8", "type": "concept", "title": "Governance and stewardship"}, {"id": "4af91aa8-f310-436e-83a5-88a6c8ffb829", "type": "concept", "title": "Financing and pooling"}, {"id": "31bb6d9f-0b51-430b-8482-441120898109", "type": "concept", "title": "Service delivery and workforce"}, {"id": "a14d76bf-8065-4114-a906-c8c2dc83ccce", "type": "concept", "title": "Medicines, information, and technology"}]}, {"id": "a1c471fe-9bd4-4d89-8e62-955d91389b14", "type": "subtopic", "title": "System archetypes and variation", "description": "No country is a pure model; institutions evolve through history and politics.", "children": [{"id": "8c4a9624-6cb5-4e7a-ab67-c5c4d93b9a6a", "type": "concept", "title": "National health service"}, {"id": "4da73e5e-43a4-4d90-89c7-1029fe672277", "type": "concept", "title": "Social health insurance"}, {"id": "3809f8e2-588a-42ee-ac3d-2caac42a25a1", "type": "concept", "title": "Pluralistic systems"}, {"id": "64315d61-cc22-45c9-8b94-526cc90bf561", "type": "concept", "title": "Decentralization and private-sector roles"}]}, {"id": "52280a57-f916-44ef-891c-1728fcbf621d", "type": "subtopic", "title": "Performance and transferability", "description": "Policy learning requires context, distribution, and implementation analysis.", "children": [{"id": "dd22c520-1420-4033-84a6-9478e97b1ded", "type": "concept", "title": "Coverage and financial protection"}, {"id": "7d7ac2e2-b7f3-4f81-9d4b-0d79d0c21d51", "type": "concept", "title": "Quality, access, and outcomes"}, {"id": "4ba29fb0-0890-479d-9794-7dadb8e54ce4", "type": "concept", "title": "Equity and responsiveness"}, {"id": "925d4a8d-d690-4b2b-ac68-c2ecfd870261", "type": "concept", "title": "Policy transfer limits"}]}]}, {"id": "ff76d120-6c53-43fb-8e37-1026e352aba8", "type": "topic", "title": "Organizational Governance, Leadership, and Strategy", "description": "Strengthens the management side of the course through mission, governance, organizational structure, leadership, strategic planning, accountability, and change.", "children": [{"id": "6023f540-e739-4815-86ab-fb21a0ec54bc", "type": "subtopic", "title": "Governance and accountability", "description": "Students understand who sets direction, oversees resources, represents communities, and answers for results.", "children": [{"id": "484bf62a-48b9-4306-b661-11ea022d065a", "type": "concept", "title": "Boards and executive leadership"}, {"id": "6a2a81d3-eef2-4e98-8f22-1c2698b4c91a", "type": "concept", "title": "Mission and public value"}, {"id": "cd113b3a-88a7-4625-a6ac-a4111f3311ce", "type": "concept", "title": "Transparency and conflicts of interest"}, {"id": "9365e0de-04e9-4630-b3db-577b1eba39d4", "type": "concept", "title": "Community accountability"}]}, {"id": "415864ff-4553-4fdc-a0f3-c5d30b77c29b", "type": "subtopic", "title": "Leadership and organizational behavior", "description": "Management depends on culture, motivation, communication, teams, and power.", "children": [{"id": "01d42cdf-e05c-4862-94ae-3a1886965188", "type": "concept", "title": "Leadership styles"}, {"id": "bbf2fc58-dd36-4c0f-b0fd-0cfe2491253b", "type": "concept", "title": "Psychological safety"}, {"id": "729241b2-e246-4b50-a9e2-2611f5bc385a", "type": "concept", "title": "Decision-making and conflict"}, {"id": "f95ba55c-819d-4726-a729-51d682befa5d", "type": "concept", "title": "Ethics and professional integrity"}]}, {"id": "ee0a88cf-1cf3-4b27-938d-074fa3da2142", "type": "subtopic", "title": "Strategic planning and change", "description": "Organizations need a credible route from environmental analysis to priorities and execution.", "children": [{"id": "4b6dc815-dee0-4c97-9645-6866968f5001", "type": "concept", "title": "SWOT/environmental scan"}, {"id": "f5c3cf82-0d7b-4193-a2ac-9e98f2e2de45", "type": "concept", "title": "Theory of change"}, {"id": "317e85d6-7007-4a61-8c0f-a6828afe7d21", "type": "concept", "title": "Strategic objectives and portfolios"}, {"id": "05c0bb0c-fa13-464b-9f72-d5bfddcf9fa4", "type": "concept", "title": "Change management"}]}]}, {"id": "bd737f36-4c27-4099-a552-5ec0d9ed097f", "type": "topic", "title": "Public Health Finance, Budgeting, Workforce, and Operations", "description": "Builds practical management competence in budgets, grants, staffing, labor, procurement, workflow, and operational stewardship.", "children": [{"id": "afeda577-e389-4b02-894f-b580f0c5741e", "type": "subtopic", "title": "Budgeting and financial stewardship", "description": "Students translate goals into resource choices and readable financial plans.", "children": [{"id": "c12d9e7e-1bf0-434c-aadf-39a04bb986dd", "type": "concept", "title": "Operating and program budgets"}, {"id": "f0b1fcf4-83f5-417e-b5f0-78a991665e46", "type": "concept", "title": "Fixed and variable costs"}, {"id": "08d7f2ca-9dcc-4965-8773-1f5173206584", "type": "concept", "title": "Grant restrictions"}, {"id": "91a3db08-a078-4524-b46a-f8aeb0a2da12", "type": "concept", "title": "Variance and scenario analysis"}]}, {"id": "0ad38fd1-57d8-46e0-8e70-c3f276b252e9", "type": "subtopic", "title": "Workforce management", "description": "A competent, diverse, supported workforce is a core public health capability.", "children": [{"id": "d5000886-abab-4476-adcb-5dfec77ddebd", "type": "concept", "title": "Workforce planning"}, {"id": "dc0f1355-6c12-4b04-acd1-4b04486fb319", "type": "concept", "title": "Recruitment and retention"}, {"id": "4e8e343b-e813-4ca9-8094-4fb3ac76b6d0", "type": "concept", "title": "Competency and training"}, {"id": "36d4ed24-961e-431d-98a0-32f03433484e", "type": "concept", "title": "Burnout, labor relations, and succession"}]}, {"id": "4cdcde11-2668-402a-87ea-a1b3ea34cc2b", "type": "subtopic", "title": "Operations and procurement", "description": "Reliable services depend on processes, supplies, contracts, facilities, and continuity.", "children": [{"id": "ded39ead-1923-420f-9552-5ea04bfd4618", "type": "concept", "title": "Workflow and capacity"}, {"id": "8560fc70-c9ad-406f-8914-3fd18c739814", "type": "concept", "title": "Procurement and contracting"}, {"id": "221fa5a1-aa6b-40da-8d7e-2ced430fd9b0", "type": "concept", "title": "Inventory and supply chains"}, {"id": "45c4bda6-75b9-4677-a4f8-d64c7dcf65c2", "type": "concept", "title": "Service-level and vendor performance"}]}]}, {"id": "96607ea2-1f9c-4943-8056-c829d5654904", "type": "topic", "title": "Policy Analysis, Economics, and Decision Support", "description": "Provides transparent tools for defining problems, comparing options, estimating impacts, analyzing distribution, and communicating recommendations.", "children": [{"id": "1c9c1d8a-3ee8-45f3-853e-d169176ebf20", "type": "subtopic", "title": "Structured policy analysis", "description": "Students create transparent comparisons rather than advocating from preference alone.", "children": [{"id": "f691752b-8536-4735-8c26-88017f9dd7ea", "type": "concept", "title": "Problem statement"}, {"id": "02443b63-547b-4a35-82b4-7cbc8a575825", "type": "concept", "title": "Criteria and alternatives"}, {"id": "8590fb28-371c-4782-9516-1f62b835345d", "type": "concept", "title": "Evidence matrix"}, {"id": "124c162b-0702-45c1-b861-c2629c69b535", "type": "concept", "title": "Recommendation and uncertainty"}]}, {"id": "5497fa0a-0ede-4fc1-a7b5-a8175357c12c", "type": "subtopic", "title": "Economic evaluation", "description": "Resource constraints require attention to opportunity cost and distribution.", "children": [{"id": "eb3d7a5b-81ec-48e7-9e29-972977464673", "type": "concept", "title": "Cost analysis and budget impact"}, {"id": "a0b53948-1f0c-4583-b481-b2a064410fb5", "type": "concept", "title": "Cost-effectiveness and cost–benefit concepts"}, {"id": "cc8ad2fc-9330-48bd-b246-ba6deac98bb7", "type": "concept", "title": "Marginal analysis"}, {"id": "887b1442-3dcb-4e11-b420-1dc627bb869c", "type": "concept", "title": "Discounting and sensitivity analysis"}]}, {"id": "d316c4fe-26a7-485c-aefd-8b86a0a7eba8", "type": "subtopic", "title": "Distribution and feasibility", "description": "An efficient policy may still be inequitable, illegal, administratively impossible, or politically fragile.", "children": [{"id": "5211fae0-53bd-4f4c-b97b-5764a4a6d6f4", "type": "concept", "title": "Equity impact assessment"}, {"id": "63d75c9e-dc7e-418e-955c-9aaf3ec002c9", "type": "concept", "title": "Administrative burden"}, {"id": "a48c8515-bf4a-45bf-aeb6-4e2c97f5ce3c", "type": "concept", "title": "Legal and operational feasibility"}, {"id": "325c8c58-ba93-4fc1-8be8-9c113824177a", "type": "concept", "title": "Political acceptability"}]}]}, {"id": "0891b9ba-a582-4e9b-83fb-eb85bcd87b10", "type": "topic", "title": "Implementation, Program Management, and Learning Health Systems", "description": "Connects enacted policy to real-world delivery through implementation science, project management, information systems, adaptation, and feedback.", "children": [{"id": "fa74bb6c-991f-4788-84ad-3bc6942c9b79", "type": "subtopic", "title": "Implementation determinants", "description": "Students identify why evidence-based policies succeed in one setting and fail in another.", "children": [{"id": "35139ced-9455-46e9-9ff1-81019788fdc3", "type": "concept", "title": "Context and readiness"}, {"id": "ee31bd8c-4e99-42a2-b073-62d8a090d3ac", "type": "concept", "title": "Fidelity and adaptation"}, {"id": "506a5a90-4ed1-4cb6-8334-e80f828b278f", "type": "concept", "title": "Implementation strategies"}, {"id": "36faa80e-40e5-4774-a146-bdba3d96bf2a", "type": "concept", "title": "Reach, adoption, and sustainability"}]}, {"id": "2ab1ac40-08ae-4815-a0b8-18a8278abe8f", "type": "subtopic", "title": "Project and program management", "description": "Clear scope, ownership, timing, dependencies, and risks turn policy into delivery.", "children": [{"id": "499d9661-d3a7-42b3-9c9e-ad4682bb8abe", "type": "concept", "title": "Work breakdown and milestones"}, {"id": "33dd540e-9573-47e3-b4ba-11c37f19dda1", "type": "concept", "title": "Roles and governance"}, {"id": "18bc1a6b-e194-4cc6-8f11-30afac0fe695", "type": "concept", "title": "Risk register"}, {"id": "b20518b1-10ca-49d5-bfae-0b76554f81eb", "type": "concept", "title": "Stakeholder communication"}]}, {"id": "cb863766-defc-4917-9fae-adfdff215896", "type": "subtopic", "title": "Data and learning systems", "description": "Organizations improve when data cycles are timely, trusted, actionable, and connected to decisions.", "children": [{"id": "ac663e29-86d1-47e8-a66f-e0e7fbea2b10", "type": "concept", "title": "Performance indicators"}, {"id": "c5209559-48dc-400d-8db4-ced4b228e415", "type": "concept", "title": "Data governance"}, {"id": "05ce3b03-d404-4443-bad9-a02776eb0c59", "type": "concept", "title": "Feedback loops"}, {"id": "2eec0bc3-0a94-4e03-8d5d-0b20dcc5fa26", "type": "concept", "title": "Rapid-cycle evaluation and scale-up"}]}]}, {"id": "8a8f1029-0be5-420c-a69c-e44ae4d02bfb", "type": "topic", "title": "Health Equity, Community Governance, and Structural Determinants", "description": "Centers distributional consequences, structural inequity, community power, cultural responsiveness, and accountability in policy and management.", "children": [{"id": "b6a597b4-2e3e-412a-8f6d-bfdadfe48889", "type": "subtopic", "title": "Structural determinants", "description": "Students connect health patterns to policies governing wealth, place, labor, education, housing, and power.", "children": [{"id": "9b7d2ae5-3fa8-4492-b4a9-93665070b173", "type": "concept", "title": "Structural racism"}, {"id": "cb433ed2-9a6c-4c71-b06a-d2f8173cafcd", "type": "concept", "title": "Economic and labor policy"}, {"id": "653c765c-7242-445e-ab36-89c40b68bcd8", "type": "concept", "title": "Housing and environmental conditions"}, {"id": "9f43f4db-8a9c-46ab-ae82-6bb5dfe14522", "type": "concept", "title": "Immigration, disability, and carceral systems"}]}, {"id": "24081ef9-9b90-4199-a0fe-e97faa852dad", "type": "subtopic", "title": "Equity analysis", "description": "Average effects can conceal who benefits, who pays, and who is excluded.", "children": [{"id": "3f665653-9273-4da0-9f8e-d132e66db120", "type": "concept", "title": "Disaggregated data"}, {"id": "edfe4530-077c-49a3-b786-053507155a9d", "type": "concept", "title": "Distributional impact"}, {"id": "cb1ef9cf-54f4-4c60-a785-eb28bb1beb9d", "type": "concept", "title": "Intersectionality"}, {"id": "8143c14f-ccc8-49aa-bc88-33d604a6c42e", "type": "concept", "title": "Proportionate universalism concept"}]}, {"id": "8df7b403-9909-4a15-bff5-36ad558e5274", "type": "subtopic", "title": "Community power and accountability", "description": "Communities should help define problems, govern resources, and evaluate results.", "children": [{"id": "e594a2c3-0bb4-43b9-ba3a-3e253daac0db", "type": "concept", "title": "Community-based participatory approaches"}, {"id": "6b79ce5d-6c6e-4396-9ec7-a8eb4e7fb31f", "type": "concept", "title": "Compensated participation"}, {"id": "3ce1c797-fdb1-4428-8946-e7faf6b56e1a", "type": "concept", "title": "Participatory budgeting"}, {"id": "0eed1d9e-d5a5-44ca-ab36-b2ae5464974f", "type": "concept", "title": "Grievance and accountability mechanisms"}]}]}, {"id": "8758ff32-de80-41b4-b4f4-2898b11f29fd", "type": "topic", "title": "Emergency Preparedness, Resilience, and Crisis Governance", "description": "Examines how systems anticipate, govern, finance, communicate, and recover from outbreaks, disasters, supply shocks, and climate-related threats.", "children": [{"id": "17726a9f-e312-484e-844a-581f0e93556c", "type": "subtopic", "title": "Preparedness and incident governance", "description": "Students map authority, command, coordination, and continuity before a crisis.", "children": [{"id": "6f4a8362-3a1a-4ed6-92b7-3a74b1186ef0", "type": "concept", "title": "Hazard vulnerability assessment"}, {"id": "8be117ff-4334-481a-8330-a47bb6628ced", "type": "concept", "title": "Incident command and emergency operations"}, {"id": "711ca2b2-4ef0-4474-9538-2716c4367f18", "type": "concept", "title": "Continuity of operations"}, {"id": "667b579a-fa65-4288-ad25-2b1be105340a", "type": "concept", "title": "Mutual aid"}]}, {"id": "d5f4d3e4-4ee7-4d7e-8f01-152f0c57d5e7", "type": "subtopic", "title": "Resource allocation and communication", "description": "Scarcity and uncertainty require transparent prioritization and trusted communication.", "children": [{"id": "0b7b863d-1e0a-4ce0-8f5f-9d4e308041eb", "type": "concept", "title": "Crisis standards and allocation ethics"}, {"id": "79282b87-5794-4cf0-8f6c-a498810daa69", "type": "concept", "title": "Risk communication"}, {"id": "497435bf-cbc8-41f0-ab74-73cfe4ce8afa", "type": "concept", "title": "Data sharing and privacy"}, {"id": "526a4bb7-0a81-4bb9-8608-c4d528d9a263", "type": "concept", "title": "Supply and workforce surge"}]}, {"id": "69e1b806-0647-46bd-94dd-b70995185f54", "type": "subtopic", "title": "Resilience and recovery", "description": "A resilient system learns, adapts, maintains essential services, and repairs inequities.", "children": [{"id": "23c2a525-80af-42e5-b91a-9414599137ee", "type": "concept", "title": "After-action review"}, {"id": "af7f7555-1026-4e4e-9078-c19d56b50336", "type": "concept", "title": "Recovery governance"}, {"id": "87e82615-1421-4727-9aa8-d7a51c4106b0", "type": "concept", "title": "Climate resilience"}, {"id": "a15333a4-e215-4e18-8a98-2d301220d211", "type": "concept", "title": "Institutional learning and trust repair"}]}]}, {"id": "252dce75-b48b-4b19-a1f1-3350006d8b07", "type": "topic", "title": "Future of Health Policy and Integrative Policy Lab", "description": "Synthesizes digital health, AI, climate, aging, workforce, fiscal pressure, trust, and reform into an applied policy analysis and management capstone.", "children": [{"id": "155a7adb-1894-4476-8752-f7c2aa3d934f", "type": "subtopic", "title": "Emerging system pressures", "description": "Students analyze interacting trends instead of treating each innovation or crisis in isolation.", "children": [{"id": "8ab2e3a6-1aaf-468f-8a06-4ec111d5ffe5", "type": "concept", "title": "Aging and chronic disease"}, {"id": "4bda0c40-d77c-4bee-87c0-a78a91704c41", "type": "concept", "title": "Climate and migration"}, {"id": "62cc8b6a-661c-4ff1-a8ed-447f744d06fc", "type": "concept", "title": "Workforce shortages"}, {"id": "c9142120-5690-4824-a67d-c26e1926b0e3", "type": "concept", "title": "Fiscal pressure and market consolidation"}]}, {"id": "31175377-8a79-4902-9867-8199ca04d913", "type": "subtopic", "title": "Digital health and AI governance", "description": "Technology policy must address evidence, access, privacy, bias, accountability, and workflow.", "children": [{"id": "28ebbe1c-4cc9-472b-9dce-3442b5fb43c7", "type": "concept", "title": "Telehealth and digital access"}, {"id": "c9356f25-b568-4e35-94f1-65c18e8c1d0c", "type": "concept", "title": "Algorithmic bias and validation"}, {"id": "0d45e119-4611-40a8-8db1-9ba42bc32458", "type": "concept", "title": "Data governance and cybersecurity"}, {"id": "f58c8cce-52fc-409b-8fef-553a177c1510", "type": "concept", "title": "Automation and workforce redesign"}]}, {"id": "cf6b2e5b-fe64-4b93-b99c-7951639a5147", "type": "subtopic", "title": "Integrative policy lab", "description": "Students synthesize policy and management into an implementable, financed, equitable proposal.", "children": [{"id": "a741ff68-75bd-4426-9556-7b9b0a5c0883", "type": "concept", "title": "Policy memo and stakeholder map"}, {"id": "c1661135-bbc9-4f6f-8f66-2773e4e3342e", "type": "concept", "title": "Governance and budget"}, {"id": "72d8b9ba-5ea2-4a8e-9919-de215e08dcd9", "type": "concept", "title": "Implementation and evaluation plan"}, {"id": "44df4b3a-4c5c-4ad3-a6d6-f4e68f2ecd9d", "type": "concept", "title": "Public presentation and defense"}]}]}], "dbBacked": true}$hpmjson$::jsonb,
