update public.learning_paths
set
  title = 'Health Policy and Management',
  goal = 'Health Policy and Management',
  summary = 'A Year 3 core course that equips undergraduate public health students to understand, analyze, manage, and improve health policies, healthcare organizations, and public health systems. It integrates institutions, federalism, financing, coverage, access, quality, law, politics, comparative systems, leadership, budgeting, workforce, implementation, equity, emergency resilience, and applied policy analysis.',
  data = $hpmjson${"slug": "health-policy-and-management", "title": "Health Policy and Management", "description": "A Year 3 core course that equips undergraduate public health students to understand, analyze, manage, and improve health policies, healthcare organizations, and public health systems. It integrates institutions, federalism, financing, coverage, access, quality, law, politics, comparative systems, leadership, budgeting, workforce, implementation, equity, emergency resilience, and applied policy analysis.", "topics": [{"id": "12c59872-5924-4a5f-8fcf-79e7ab4961cc", "type": "topic", "title": "Health Policy Process", "description": "Introduces how problems reach agendas, policy alternatives are developed, decisions are authorized, programs are implemented, and outcomes feed back into future policy.", "children": [{"id": "4d746a31-c5bc-4ba8-9d59-5949c65222ad", "type": "subtopic", "title": "Problem definition and agenda setting", "description": "Students learn that how a problem is framed determines which solutions and stakeholders become legitimate.", "children": [{"id": "f558af54-1f93-40d1-be73-642dbe031e33", "type": "concept", "title": "Indicators, focusing events, and feedback"}, {"id": "0ca9f5f2-c037-44ab-89b6-a160bdf12bee", "type": "concept", "title": "Problem frames and causal stories"}, {"id": "ac8a0507-8fb7-4d93-a0ac-5b523e046492", "type": "concept", "title": "Agenda windows"}, {"id": "1ca3a0d4-518c-46c2-8494-86a2a3a6eecc", "type": "concept", "title": "Issue attention cycles"}]}, {"id": "1f8f9dac-2e5d-4dae-8406-57ed738a7d88", "type": "subtopic", "title": "Formulation and adoption", "description": "Policy alternatives must survive evidence, values, legal authority, politics, and procedural rules.", "children": [{"id": "d3a180cc-ee3f-4a2b-8731-7c33d794ab1a", "type": "concept", "title": "Legislative and administrative pathways"}, {"id": "1ab8b6dc-1e9e-4067-8831-5b6d42f9c614", "type": "concept", "title": "Policy instruments"}, {"id": "69b79f35-d954-46a2-a0ed-ad5a3c93910d", "type": "concept", "title": "Committee, rulemaking, and budgeting processes"}, {"id": "f0ffe53b-21f5-4637-8152-6511378d7dde", "type": "concept", "title": "Coalitions and negotiation"}]}, {"id": "04b72467-5118-4ad6-9baa-7fd8e32873a7", "type": "subtopic", "title": "Implementation and evaluation", "description": "Adoption is only the midpoint; delivery capacity and feedback determine actual effects.", "children": [{"id": "4d0f3bc2-9323-493b-b890-f76a924c049c", "type": "concept", "title": "Administrative discretion"}, {"id": "f29f6878-a40f-495d-822c-2cc9359131e6", "type": "concept", "title": "Implementation fidelity and adaptation"}, {"id": "676bad5f-56dd-4ff2-82c8-47f4a151723e", "type": "concept", "title": "Process, outcome, and impact evaluation"}, {"id": "c7f30582-d330-44db-b04e-340e0b6986c2", "type": "concept", "title": "Policy feedback and termination"}]}]}, {"id": "2fcfdd99-1920-4566-8c01-86ad1635e483", "type": "topic", "title": "Federal Health Institutions and Intergovernmental Relations", "description": "Maps the authorities, incentives, data, financing, regulation, and coordination roles of federal institutions and their relationships with states, tribes, territories, and localities.", "children": [{"id": "61116902-9f6a-468b-bcc5-e05855894b10", "type": "subtopic", "title": "Federal actors and functions", "description": "Students map who finances, regulates, researches, delivers, and coordinates health policy.", "children": [{"id": "9dd425aa-97e6-43e0-8344-1693d7af71f9", "type": "concept", "title": "HHS, CDC, CMS, FDA, NIH, HRSA, and AHRQ"}, {"id": "dc88e091-aabe-40af-869d-99d5e6bc9a9c", "type": "concept", "title": "Congress and the executive branch"}, {"id": "6b4f148e-521c-4627-b41f-cc1a9c400328", "type": "concept", "title": "Courts and independent bodies"}, {"id": "8c2cddbe-3f91-4435-a615-19f3b07e4286", "type": "concept", "title": "Federal data and accountability systems"}]}, {"id": "edcebc8f-4fd6-446a-861a-3fffc13aa37d", "type": "subtopic", "title": "Federalism", "description": "Shared authority creates innovation and responsiveness as well as fragmentation and inequity.", "children": [{"id": "9d6b9de3-ef56-4e8f-9e1b-c5546c98bd98", "type": "concept", "title": "Enumerated and reserved powers"}, {"id": "c129f89f-1ea0-4042-aae2-790fd258f98d", "type": "concept", "title": "Grants, waivers, and conditions"}, {"id": "34571928-2f53-4386-b88f-46f3821e700f", "type": "concept", "title": "Preemption"}, {"id": "8e78714a-6401-467e-87a3-5403a74c5387", "type": "concept", "title": "Interstate variation"}]}, {"id": "40dccf11-4adb-4393-91c9-999bd661c617", "type": "subtopic", "title": "Intergovernmental coordination", "description": "Public health threats and programs cross borders and require clear roles and mutual support.", "children": [{"id": "bd1fda86-3676-434d-a05d-78b0f99c8817", "type": "concept", "title": "Federal–state–local relationships"}, {"id": "3f410278-650d-4032-ba91-5bd216c909fe", "type": "concept", "title": "Tribal sovereignty"}, {"id": "edca6dc8-c766-43f2-b10d-7db577d1c62a", "type": "concept", "title": "Territories and freely associated states"}, {"id": "b49447bf-ac17-441d-a770-d3d6a56bd804", "type": "concept", "title": "Mutual aid and cross-jurisdiction agreements"}]}]}, {"id": "1b4822c1-8413-4606-9df1-892111787575", "type": "topic", "title": "State, Tribal, Territorial, and Local Public Health Systems", "description": "Shows how public health authority and service delivery vary across jurisdictions and how agencies work with healthcare, community, and cross-sector partners.", "children": [{"id": "ae10ed3f-cd42-4169-87b5-10d5801a1707", "type": "subtopic", "title": "System structures", "description": "Students compare centralized, decentralized, shared, and mixed governance arrangements.", "children": [{"id": "c8ec4604-f5d1-4ec4-a129-dd2fb927d366", "type": "concept", "title": "State health agencies"}, {"id": "6f64c08c-fb5e-4011-852c-b858c179597b", "type": "concept", "title": "Local health departments"}